'use strict';const fs=require('node:fs'),path=require('node:path'),assert=require('node:assert/strict'),crypto=require('node:crypto');const repo=path.resolve(__dirname,'../../..'),base=path.join(repo,'.artifacts/deep-audit-question-delivery'),sha=b=>crypto.createHash('sha256').update(b).digest('hex'),walk=d=>fs.readdirSync(d,{withFileTypes:true}).flatMap(e=>e.isDirectory()?walk(path.join(d,e.name)):e.isFile()?[path.join(d,e.name)]:[]);const out=path.join(base,'source-remap-v2');assert.ok(!fs.existsSync(out));fs.mkdirSync(out);const norm=f=>f.replaceAll('\\','/');const needed=new Map();for(const file of walk(base).filter(f=>path.basename(f)==='source-before.json'))for(const e of JSON.parse(fs.readFileSync(file))){const f=path.join(repo,e.file);if(!fs.existsSync(f)||sha(fs.readFileSync(f))!==e.sha256){const key=e.sha256;const r=needed.get(key)||{file:e.file,sha256:e.sha256,manifests:[]};r.manifests.push(norm(path.relative(repo,file)));needed.set(key,r)}}const candidates=new Map();for(const file of walk(base).filter(f=>/\.(cjs|mjs|js)$/.test(f))){const h=sha(fs.readFileSync(file));if(needed.has(h)&&!candidates.has(h))candidates.set(h,norm(path.relative(repo,file)))}
// Reconstruct one interrupted producer state from the subsequent saved producer by removing only the measured button fix. Validate by historical SHA before using it.
const producer=path.join(base,'recovery-derived-v2/producer.mjs');if(fs.existsSync(producer)){const original=fs.readFileSync(producer,'utf8'),needle='style: { minHeight: 44, padding: "8px 12px" }, ';if(original.split(needle).length===2){const recovered=original.replace(needle,''),h=sha(recovered);if(needed.has(h)&&!candidates.has(h)){const file=path.join(out,'recovered-pre-button-producer.mjs');fs.writeFileSync(file,recovered,{flag:'wx'});candidates.set(h,norm(path.relative(repo,file)))}}}
const result=[...needed.values()].map(e=>({...e,originalBytes:candidates.get(e.sha256)??null}));fs.writeFileSync(path.join(out,'mapping.json'),JSON.stringify({purpose:'Explicit historical bytes mapping only; old source-before/freezes/pins never rewritten. Reconstructed producer is SHA-bound, not claimed as originally saved.',files:result},null,2));console.log(JSON.stringify({mapped:result.filter(e=>e.originalBytes).length,unmapped:result.filter(e=>!e.originalBytes)}));assert.ok(result.every(e=>e.originalBytes),'every historical changed input must have exact original bytes');